head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _19 : dummy_xlsstyle_rownum (Excel 파일 스타일 옵션 - 행번호 열) 계열 중 Footer / SubTotal 영역 서식 옵션
//     - rowNumFooterColor / rowNumFooterFontName / rowNumFooterFontSize / rowNumFooterFontColor
//       / rowNumSubTotalColor / rowNumSubTotalFontName / rowNumSubTotalFontSize / rowNumSubTotalFontColor
//     같은 계열의 행번호 열 표시 옵션과 Header / Body 영역 서식 옵션 10 개는 _18 에서 다룬다.
//     _15 (Header/Body) / _16 (SubTotal/Footer) / _17 (GroupBy/줄무늬) / _18 (행번호 열 표시·Header·Body) 과 대칭 구성이며
//     description 은 분리 샘플 공통(_1 과 동일).
scwin.tData = {
    "description" : "[gridView > M > advancedExcelDownload]<br/>GridView 컴포넌트의 데이터를 Excel 파일로 다운로드합니다.",
    "validation" : [
        "rowNumFooterColor(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Footer 영역 배경색을 설정합니다.",
        "rowNumFooterColor(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumFooterFontName(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Footer 영역 폰트 이름을 설정합니다.",
        "rowNumFooterFontName(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumFooterFontSize(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Footer 영역 폰트 크기를 설정합니다.",
        "rowNumFooterFontSize(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumFooterFontColor(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 Footer 영역 폰트 색상을 설정합니다.",
        "rowNumFooterFontColor(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumSubTotalColor(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 SubTotal 영역 배경색을 설정합니다.",
        "rowNumSubTotalColor(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumSubTotalFontName(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 SubTotal 영역 폰트 이름을 설정합니다.",
        "rowNumSubTotalFontName(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumSubTotalFontSize(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 SubTotal 영역 폰트 크기를 설정합니다.",
        "rowNumSubTotalFontSize(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
        "rowNumSubTotalFontColor(선택) 파라미터로 rowNumVisible 파라미터값이 'true' 일때 행번호 열의 SubTotal 영역 폰트 색상을 설정합니다.",
        "rowNumSubTotalFontColor(선택) 파라미터를 생략하면 기본값 '' 이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : Header 1줄(병합 없음) / Body 6행 / SubTotal(부서 기준 3그룹) / Footer 1행 의 GridView 를 동적 생성한다.
//  · advancedExcelDownload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
//  · 본 계열은 Excel 파일에 추가되는 행번호 열의 Footer 영역 / SubTotal 영역 서식만 확인하므로 두 영역을 모두 둔다.
//  · Body Column 인덱스 0:부서 1:사원명 2:실적건수 3:실적금액
//  · SubTotal : targetColumnID='dept' 기준 소계 행 3행 / Footer : 합계 행 1행
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- Header 는 1줄(병합 없음), Body Column 인덱스 0 부서 / 1 사원명 / 2 실적건수(number) / 3 실적금액(number), Body Row 는 6행\n- SubTotal 은 부서 기준 3그룹(영업기획팀 / 고객지원팀 / 품질관리팀)이라 소계 행이 3행 생성되고, Footer 는 합계 행 1행이다\n- 행번호 열은 GridView 화면에는 없고 Excel 파일에만 추가되는 첫 번째 열 A 이다. Body 에는 1 부터의 번호가 숫자로 채워지고, SubTotal 행과 Footer 행의 행번호 열 셀은 빈 값이다\n- rowNumVisible true 는 행번호 열을 파일에 추가하기 위한 고정 전달값이다. 이 8 개 옵션은 rowNumVisible 이 true 일 때만 요청에 담기므로 본 계열 검증의 전제이며 검증 대상은 아니다(_18 에서 다룬다)\n- useSubTotal true 는 SubTotal 행을 파일에 포함시키기 위한 고정 전달값(본 계열 검증 대상 아님)\n- useStyle 은 전달하지 않는다. 이 8 개 옵션은 useStyle 없이도 적용된다\n- 파일명 download_xlsstyle_rnsf, 확장자 xlsx 고정 전달(본 계열 검증 대상 아님)\n[절차]\n1. par 옵션(rowNumFooterColor / rowNumFooterFontName / rowNumFooterFontSize / rowNumFooterFontColor / rowNumSubTotalColor / rowNumSubTotalFontName / rowNumSubTotalFontSize / rowNumSubTotalFontColor) 값을 선택한다\n2. advancedExcelDownload 버튼을 클릭해 Excel 파일을 내려받는다\n[확인]\n- 이 계열은 Cell 값이 아니라 셀 서식만 바꾸므로 값만 봐서는 차이가 보이지 않는다. 내려받은 파일을 Excel 로 열어 행번호 열(첫 번째 열)의 소계 행 3개와 합계 행 1개로 확인한다\n- 행번호 열의 소계 행 / 합계 행 셀은 값이 없는 빈 셀이라 확인 수단이 옵션마다 다르다. 배경색 2 개는 빈 셀이어도 채우기가 보이므로 시트에서 바로 확인된다\n- 글꼴 3 개는 표시할 글자가 없어 시트를 그냥 봐서는 차이가 없다. 해당 셀을 선택한 뒤 Excel 리본의 글꼴 이름 / 글꼴 크기 / 글꼴 색 표시로 확인한다\n- 행번호 열의 소계 행 / 합계 행에 값을 넣는 파라미터는 없다. rowNumHeaderValue 는 Header 셀 전용이라 소계 행 / 합계 행에는 적용되지 않는다. 글꼴 크기를 키워도 행 높이는 변하지 않는다\n- 서식 8 개를 모두 미설정하면 행번호 열은 소계 행이 연한 파랑(#D9E3EF), 합계 행이 연한 민트(#E3FFF2) 채우기이고 두 영역 모두 Calibri 11 글꼴이다. 각 옵션의 미설정 확인은 이 기본 서식과 대조한다\n- rowNumFooterColor : 설정한 색(#FFFF00)이 행번호 열 Footer 셀의 채우기 색이 되는지 (시트에서 바로 확인)\n- rowNumFooterFontName : 행번호 열 Footer 셀을 선택했을 때 글꼴 이름이 설정한 값(굴림)으로 표시되는지\n- rowNumFooterFontSize : 행번호 열 Footer 셀을 선택했을 때 글꼴 크기가 설정한 값(16)으로 표시되는지\n- rowNumFooterFontColor : 행번호 열 Footer 셀을 선택했을 때 글꼴 색이 설정한 값(#FF0000)으로 표시되는지\n- rowNumSubTotalColor : 설정한 색(#CCFFCC)이 행번호 열 소계 행 3개 셀의 채우기 색이 되는지 (시트에서 바로 확인)\n- rowNumSubTotalFontName : 행번호 열 소계 행 셀을 선택했을 때 글꼴 이름이 설정한 값(굴림)으로 표시되는지\n- rowNumSubTotalFontSize : 행번호 열 소계 행 셀을 선택했을 때 글꼴 크기가 설정한 값(20)으로 표시되는지\n- rowNumSubTotalFontColor : 행번호 열 소계 행 셀을 선택했을 때 글꼴 색이 설정한 값(#0000FF)으로 표시되는지\n- 폰트 옵션(FontName / FontSize / FontColor) 중 하나만 설정해도 그 영역 글꼴이 새로 만들어져 기본 글꼴에 있던 글자색 지정이 사라진다. 그래서 기본값과 같은 값(글꼴 크기 11)을 명시해도 미설정과 완전히 같은 파일이 되지는 않는다\n- Footer 영역 옵션(4개)과 SubTotal 영역 옵션(4개)은 서로 독립이다. 한쪽만 설정하면 다른 쪽은 기본 서식으로 남는지 함께 확인한다\n- 행번호 열 서식 옵션은 행번호 열에만 적용된다. 기존 4 개 Column 의 소계 행 / 합계 행 서식은 그대로인지, 행번호 열의 Header / Body 셀 서식도 그대로인지 함께 확인한다\n- 결과창의 서버 전달값으로 실제 서버에 전송된 옵션 원문을 함께 확인한다"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 DataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="empName" name="empName" dataType="text"></w2:column>';
    strDlt += '<w2:column id="caseCnt" name="caseCnt" dataType="number"></w2:column>';
    strDlt += '<w2:column id="saleAmt" name="saleAmt" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 부서 3그룹 x 2명 의 6행 데이터 (소계 행 3행 생성)
    let jsonData = [
        { "dept" : "영업기획팀", "empName" : "김도현", "caseCnt" : 34, "saleAmt" : 18450000 },
        { "dept" : "영업기획팀", "empName" : "박서연", "caseCnt" : 27, "saleAmt" : 12300000 },
        { "dept" : "고객지원팀", "empName" : "이준호", "caseCnt" : 41, "saleAmt" : 9800000 },
        { "dept" : "고객지원팀", "empName" : "최민아", "caseCnt" : 19, "saleAmt" : 6450000 },
        { "dept" : "품질관리팀", "empName" : "정우진", "caseCnt" : 25, "saleAmt" : 15200000 },
        { "dept" : "품질관리팀", "empName" : "한지민", "caseCnt" : 30, "saleAmt" : 11750000 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 생성 (DataList 바인딩)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:700px;height:340px;">';
    strTarget += '<w2:caption style="" id="caption1" value="advancedExcelDownload (Excel 파일 스타일 옵션 - 행번호 열의 Footer / SubTotal) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol1" value="부서"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol2" value="사원명"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol3" value="실적건수"></w2:column>';
    strTarget += '<w2:column width="170" style="" inputType="text" id="hcol4" value="실적금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="empName" dataList="empName"></w2:column>';
    strTarget += '<w2:column width="*" style="text-align:right;" inputType="text" dataType="number" displayFormat="#,##0" id="caseCnt" dataList="caseCnt"></w2:column>';
    strTarget += '<w2:column width="170" style="text-align:right;" inputType="text" dataType="number" displayFormat="#,##0" id="saleAmt" dataList="saleAmt"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    // SubTotal : 부서 기준 3그룹 -> 소계 행 3행 (rowNumSubTotal 계열 옵션 확인 대상)
    strTarget += '<w2:subTotal style="" id="subTotal1" targetColumnID="dept">';
    strTarget += '<w2:row style="" id="srow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="scol1" value="소계"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="scol2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="text-align:right;" inputType="expression" dataType="number" displayFormat="#,##0" id="scol3" expression="sum(\'caseCnt\')"></w2:column>';
    strTarget += '<w2:column width="170" style="text-align:right;" inputType="expression" dataType="number" displayFormat="#,##0" id="scol4" expression="sum(\'saleAmt\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:subTotal>';
    // Footer : 합계 행 1행 (rowNumFooter 계열 옵션 확인 대상)
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="frow1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="fcol1" value="합계"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="fcol2" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="text-align:right;" inputType="expression" dataType="number" displayFormat="#,##0" id="fcol3" expression="sum(\'caseCnt\')"></w2:column>';
    strTarget += '<w2:column width="170" style="text-align:right;" inputType="expression" dataType="number" displayFormat="#,##0" id="fcol4" expression="sum(\'saleAmt\')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// par 옵션값으로 advancedExcelDownload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · 8 개 파라미터 모두 String 타입이므로 selectbox 값을 그대로 전달한다.
//  · fileName / extension / rowNumVisible / useSubTotal 은 고정값이며 본 계열의 검증 대상이 아니다.
//     - rowNumVisible : 행번호 열을 파일에 추가하기 위한 값 (이 8 개 옵션은 true 일 때만 요청에 담긴다)
//     - useSubTotal   : SubTotal 행을 파일에 포함시키기 위한 값
scwin.buildOptions = function () {
    let options = { "fileName" : "download_xlsstyle_rnsf", "extension" : "xlsx", "rowNumVisible" : "true", "useSubTotal" : "true" };
    let arrDesc = [];

    let fnSet = function (sKey, vValue) {
        options[sKey] = vValue;
        arrDesc.push(sKey + "=" + vValue);
    };

    let v;
    v = par_rowNumFooterColor.getValue();       if (v !== "") fnSet("rowNumFooterColor", v);
    v = par_rowNumFooterFontName.getValue();    if (v !== "") fnSet("rowNumFooterFontName", v);
    v = par_rowNumFooterFontSize.getValue();    if (v !== "") fnSet("rowNumFooterFontSize", v);
    v = par_rowNumFooterFontColor.getValue();   if (v !== "") fnSet("rowNumFooterFontColor", v);
    v = par_rowNumSubTotalColor.getValue();     if (v !== "") fnSet("rowNumSubTotalColor", v);
    v = par_rowNumSubTotalFontName.getValue();  if (v !== "") fnSet("rowNumSubTotalFontName", v);
    v = par_rowNumSubTotalFontSize.getValue();  if (v !== "") fnSet("rowNumSubTotalFontSize", v);
    v = par_rowNumSubTotalFontColor.getValue(); if (v !== "") fnSet("rowNumSubTotalFontColor", v);

    return { "options" : options, "desc" : ((arrDesc.length === 0) ? "{} (rowNumFooterColor / rowNumFooterFontName / rowNumFooterFontSize / rowNumFooterFontColor / rowNumSubTotalColor / rowNumSubTotalFontName / rowNumSubTotalFontSize / rowNumSubTotalFontColor 전체 생략)" : arrDesc.join(" / ")) };
}



// 다운로드 요청 캡처 : 다운로드는 숨겨진 iframe 으로 form 전송되며 form 은 전송 직후 제거되므로,
//  메소드 호출 구간에서만 form submit 을 감싸 서버로 실제 전달되는 값을 읽고 곧바로 원복한다. (실제 요청은 그대로 통과)
scwin.hookRequest = function () {
    scwin.gVar = { "body" : "" };

    let fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        if (scwin.gVar.body === "") {
            let objInput = this.querySelector("input[name=xmlValue]");
            scwin.gVar.body = (objInput === null) ? "" : objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };

    scwin.gVar.unhook = function () {
        HTMLFormElement.prototype.submit = fnSubmit;
    };
}



// 캡처한 요청 본문에서 서버로 전달된 옵션값을 읽는다. (전달되지 않은 옵션은 미전달로 표시)
//  · 이 계열 8 개는 파라미터명과 전송 키가 같다.
scwin.getSentValue = function (sParamName) {
    let sBody = scwin.gVar.body || "";
    let nKey = sBody.indexOf("hashkey='" + sParamName + "'");
    if (nKey < 0) return "(미전달)";

    let sRest = sBody.substring(nKey);
    let nVal = sRest.indexOf("value='");
    if (nVal < 0) return "(미전달)";

    sRest = sRest.substring(nVal + 7);
    return sRest.substring(0, sRest.indexOf("'"));
}



// advancedExcelDownload 실행
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let objBuild = scwin.buildOptions();

    scwin.hookRequest();
    try {
        target1.advancedExcelDownload(objBuild.options);
    } finally {
        scwin.gVar.unhook();
    }

    bottom.setReturnValue("전달 옵션 : " + objBuild.desc);
    bottom.setReturnValue("서버 전달값(Footer) : rowNumFooterColor=" + scwin.getSentValue("rowNumFooterColor") + " / rowNumFooterFontName=" + scwin.getSentValue("rowNumFooterFontName") + " / rowNumFooterFontSize=" + scwin.getSentValue("rowNumFooterFontSize") + " / rowNumFooterFontColor=" + scwin.getSentValue("rowNumFooterFontColor"));
    bottom.setReturnValue("서버 전달값(SubTotal) : rowNumSubTotalColor=" + scwin.getSentValue("rowNumSubTotalColor") + " / rowNumSubTotalFontName=" + scwin.getSentValue("rowNumSubTotalFontName") + " / rowNumSubTotalFontSize=" + scwin.getSentValue("rowNumSubTotalFontSize") + " / rowNumSubTotalFontColor=" + scwin.getSentValue("rowNumSubTotalFontColor"));
}
